using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.ComponentModel;using System.Text;using V15Voice;
public static class VoiceDiagnosticTests {
 static int count;static string root,folder;static void Check(bool b,string name){if(!b)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 sealed class Engine:KokoroEngine {public double Seconds=3.85;public int Calls,FailAt,StopAt;public bool CheckFail,Recover;public Exception Failure=new Exception("fixture TTS failed",new Win32Exception(5,"denied by fixture"));public Action<int> AfterGenerate;
 public override void CheckFiles(){if(CheckFail)throw new FileNotFoundException("fixture model absent");}
 public override Wave Generate(string text,double speed,string output){Calls++;if(Recover&&Calls==1&&RunReport!=null)RunReport.ProcessFailure("fixture worker",23,"traceback fixture",new TimeoutException("worker timeout"),true);if(Calls==StopAt)throw new OperationCanceledException("fixture cancellation");if(Calls==FailAt)throw Failure;int n=(int)Math.Round(Seconds/speed*24000);var a=new short[n];for(int i=0;i<n;i++)a[i]=i<n-1200?(short)(5000*Math.Sin(i*.061)):(short)0;if(AfterGenerate!=null)AfterGenerate(Calls);return new Wave{Rate=24000,Samples=a};}}
 static List<Cue> Cues(int n=9){return Enumerable.Range(1,n).Select(i=>new Cue{Id=i,Start=(i-1)*4,End=i*4,Text="This sentence number "+i+" ends here."}).ToList();}
 static Engine New(){return new Engine{Root=folder,VoiceName="diagnostic fixture",DeviceMode="cpu"};}
 static RenderOptions Opt(List<Cue> c,string name,bool anchored=true){string path=Path.Combine(folder,name+".srt");File.WriteAllText(path,Scripts.ToSrt(c));return new RenderOptions{CheckpointRoot=Path.Combine(folder,"stage-cache-"+name),Anchored=anchored,Locked=!anchored,BaseSpeed=1,MinSpeed=.8,MaxSpeed=1.3,Breathing=BreathMode.None,ReportContext=new VoiceReportContext{SourcePath=path,SourceCues=VoiceRenderReport.Snapshot(c)}};}
 static bool Run(List<Cue> c,Engine e,RenderOptions o,string name,Action<int,string> progress=null){try{Renderer.Render(c,e,o,Path.Combine(folder,name+".wav"),progress??((p,m)=>{}));return true;}catch{return false;}}
 static string Report(RenderOptions o){return File.ReadAllText(o.RunReport.PathName);}
 public static int Main(){string savedFfmpeg=Environment.GetEnvironmentVariable("V15_FFMPEG");try{root=AppDomain.CurrentDomain.BaseDirectory;folder=Path.Combine(Path.GetTempPath(),"V15 diagnostics "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);Directory.CreateDirectory(Path.Combine(folder,"breaths"));new Wave{Rate=24000,Samples=Enumerable.Range(0,4800).Select(i=>(short)(1000*Math.Sin(i*.071))).ToArray()}.Write(Path.Combine(folder,"breaths","test.wav"));
 var c=Cues();var o=Opt(c,"tts-failure");var e=New();e.FailAt=4;e.Failure.Data["ProcessExitCode"]=17;Check(!Run(c,e,o,"tts-failure"),"TTS failure fixture stops export");var r=o.RunReport;string text=Report(o);
 Check(r.FailureCode=="TTS_FAILED"&&r.FailureStep=="TTS"&&r.FailureUnit==4&&r.FailureStage==2,"TTS failure records exact phase/current unit/stage instead of blaming timeline");
 Check(text.Contains("System.ComponentModel.Win32Exception")&&text.Contains("Win32 native code: 5")&&text.Contains("HResult=0x")&&text.Contains("ProcessExitCode: 17")&&text.Contains("denied by fixture"),"Report retains full exception chain and native/process codes");
 Check(r.Stages.Count==3&&r.Stages[0].Status=="Đạt khung chặng"&&r.Stages[1].Status=="Lỗi tại chặng"&&r.Stages[2].Status=="Chưa chạy tới","All stages planned upfront retain pass/error/unvisited states");
 Check(!r.Stages[2].Before.HasValue&&!r.Stages[2].After.HasValue&&text.Contains(c[8].Text)&&text.Contains("Lời toàn chặng:"),"Pending stage retains complete narration without fabricated measurements");
 Check(!r.Stages[1].Tts.HasValue&&r.Units.Single(u=>u.Number==4).Before==null&&!text.Contains("Mã kết quả app: TIMELINE_MISMATCH"),"Incomplete TTS never receives a fake zero or timeline diagnosis");
 c=Cues();o=Opt(c,"cancel-stage");e=New();e.StopAt=4;Check(!Run(c,e,o,"cancel-stage")&&o.RunReport.FailureCode=="CANCELLED"&&o.RunReport.Stages[1].Status=="Đã dừng tại chặng"&&o.RunReport.Stages[2].Status=="Chưa chạy tới","Cancellation preserves completed and untouched stages");
 c=Cues();o=Opt(c,"missing-model");e=New();e.CheckFail=true;Check(!Run(c,e,o,"missing-model")&&o.RunReport.FailureStep=="MODEL"&&o.RunReport.FailureCode=="MODEL_PREFLIGHT_FAILED"&&o.RunReport.Stages.Count==3&&o.RunReport.Stages.All(s=>s.Status=="Chưa chạy tới"),"Missing model reports all planned stages as unvisited");
 c=Cues(3);o=Opt(c,"stage-overflow");e=New();e.Seconds=6;Check(!Run(c,e,o,"stage-overflow")&&o.RunReport.FailureCode=="TIMELINE_MISMATCH","Existing audio outside stage limits is classified as timeline mismatch");r=o.RunReport;var stage=r.Stages.Single();
 Check(stage.RequiredSpeed>1.49&&stage.RequiredSpeed>o.MaxSpeed&&stage.Attempts.Last().Speed<=o.MaxSpeed&&Report(o).Contains("ƯỚC TÍNH trước giới hạn"),"Unclamped required speed is distinct from bounded actual attempts");
 Check(stage.Attempts.Last().Measured-stage.Attempts.Last().Target>0&&Report(o).Contains("Lần thử CUỐI đã đo:"),"Last trial retains measured positive overflow separately from chosen best");
 c=Cues(3);o=Opt(c,"stage-underflow");e=New();e.Seconds=1;Check(!Run(c,e,o,"stage-underflow")&&o.RunReport.Stages[0].RequiredSpeed<o.MinSpeed&&o.RunReport.Stages[0].Attempts.Last().Measured-o.RunReport.Stages[0].Attempts.Last().Target<0,"Too-short stage retains unconstrained estimate and measured underflow");
 c=Cues(4);for(int i=0;i<c.Count;i++){c[i].Start=i*3.45;c[i].End=(i+1)*3.45;}c[3].AnchorAfter=true;o=Opt(c,"components");o.Punctuation=PunctuationMode.Custom;o.CommaPause=.28;o.Gap=.12;o.Breathing=BreathMode.Auto;foreach(var cue in c)cue.Text="Hello, friend number "+cue.Id+".";o.ReportContext.SourceCues=VoiceRenderReport.Snapshot(c);e=New();e.Seconds=1.55;Check(Run(c,e,o,"components"),"Custom-punctuation/breath stage fixture succeeds");r=o.RunReport;
 Check(r.Stages.All(s=>Math.Abs((s.Tts+s.InnerPauses+s.BetweenPauses+s.Breaths-s.Before).Value)<1.0/24000),"TTS, explicit inner/inter-unit pauses and breath sum to actual prefit PCM");
 Check(r.Stages.Sum(s=>s.InnerPauses)>0&&r.Stages.Sum(s=>s.Breaths)>0&&r.Stages.All(s=>s.BetweenPauses>=0),"App-inserted pauses and breaths are measured separately without double counting");
 Check(r.Units.All(u=>Math.Abs((u.Tts+u.PauseBefore-u.Before).Value)<1.0/24000)&&r.Units.All(u=>u.After==null&&u.Start==null),"Source unit audio and pauses measured; final grouped-unit times remain unknown");
 // Real failed subprocess: preserve actual exit code and captured output.
 string shim=Path.Combine(folder,"ffmpeg-fail.sh");File.WriteAllText(shim,"#!/bin/sh\necho actual-ffmpeg-fixture-error >&2\nexit 27\n");using(var chmod=System.Diagnostics.Process.Start("chmod","+x "+KokoroEngine.Q(shim)))chmod.WaitForExit();Environment.SetEnvironmentVariable("V15_FFMPEG",shim);
 c=Cues(1);c[0].End=2;o=Opt(c,"tempo-exit",false);e=New();e.Seconds=2.7;Check(!Run(c,e,o,"tempo-exit")&&o.RunReport.FailureCode=="TEMPO_PROCESS_FAILED"&&o.RunReport.FailureDetail.Contains("ProcessExitCode: 27")&&o.RunReport.FailureDetail.Contains("actual-ffmpeg-fixture-error"),"Real tempo subprocess failure retains exit code/log and exact phase");
 Check(o.RunReport.Units[0].After==null&&o.RunReport.Units[0].RequiredSpeed.HasValue,"Failed atempo retains initial estimate without inventing completed output");
 c=Cues(1);o=Opt(c,"normalize-exit",false);o.NormalizeLoudness=true;e=New();e.Seconds=3.85;Check(!Run(c,e,o,"normalize-exit")&&o.RunReport.FailureCode=="NORMALIZATION_FAILED"&&o.RunReport.FailureDetail.Contains("ProcessExitCode: 27")&&o.RunReport.Units[0].After.HasValue&&o.RunReport.Wav=="","Normalization failure is distinct from successful TTS/fitting and unpublished WAV");Environment.SetEnvironmentVariable("V15_FFMPEG",savedFfmpeg);
 c=Cues(2);o=Opt(c,"assembly-error",false);e=New();e.AfterGenerate=n=>{if(n==2)c[1].Start=0;};Check(!Run(c,e,o,"assembly-error")&&o.RunReport.FailureCode=="AUDIO_ASSEMBLY_FAILED"&&o.RunReport.FailureStep=="ASSEMBLE","Actual overlapping PCM write is reported as assembly failure");
 c=Cues(1);o=Opt(c,"publish-error",false);e=New();string parent=Path.Combine(folder,"publication"),moved=parent+"-moved";Directory.CreateDirectory(parent);bool publishFailed=false;try{Renderer.Render(c,e,o,Path.Combine(parent,"result.wav"),(p,m)=>{if(p==95)Directory.Move(parent,moved);});}catch{publishFailed=true;}Check(publishFailed&&o.RunReport.FailureCode=="WAV_PUBLISH_FAILED"&&File.Exists(o.RunReport.PathName)&&!Report(o).Contains("Mã kết quả app: TTS_FAILED"),"Output publication error preserves report beside source and correct diagnosis");
 c=Cues(1);o=Opt(c,"direct-process-log",false);e=New();e.Recover=true;Check(Run(c,e,o,"direct-process-log"),"Recovered worker fixture publishes a real WAV");r=o.RunReport;Check(r.FailureCode==""&&r.ProcessDiagnostics[0].ExitCode==23&&Report(o).Contains("Sẽ thử lại/dự phòng")&&Report(o).Contains("traceback fixture"),"Recovered subprocess diagnostic does not turn successful run into failure");
 c=LongText.Parse("This is a natural paragraph for a text export.");o=Opt(c,"txt-no-estimate",false);o.Prose=true;o.Locked=false;e=New();Check(Run(c,e,o,"txt-no-estimate")&&o.RunReport.Units.All(u=>u.RequiredSpeed==null&&u.Target==null),"Natural TXT does not invent a required timeline speed");
 c=Cues(1);c[0].End=2;o=Opt(c,"legacy-budget",false);o.Punctuation=PunctuationMode.Custom;o.CommaPause=.5;c[0].Text="Hello, friend.";o.ReportContext.SourceCues=VoiceRenderReport.Snapshot(c);e=New();e.Seconds=.9;Check(Run(c,e,o,"legacy-budget"),"Legacy pause-compression fixture renders");var unit=o.RunReport.Units[0];Check(unit.PauseAfter<unit.PauseBefore&&Math.Abs(unit.RequiredSpeed.Value-o.BaseSpeed*unit.WorkingBefore.Value/unit.Target.Value)<1e-9,"Legacy speed estimate uses measured post-pause-compression input and real fit budget");
 Console.WriteLine("TOTAL VOICE DIAGNOSTICS "+count+" passed. Fixtures: "+folder);return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}finally{Environment.SetEnvironmentVariable("V15_FFMPEG",savedFfmpeg);}}
}
